const EQ = (field,value)=>({field,op:'eq',value});
const IN = (field,value)=>({field,op:'in',value});
const equipment = {
  10:['sword','剑'],11:['axe','斧'],12:['spear','枪'],13:['hammer','槌'],
  14:['bow','弓'],15:['machine','机械'],16:['claw','爪'],17:['staff','法杖'],
  20:['armor','铠甲'],21:['clothes','衣服'],22:['robe','长袍']
};
const elements = {0:['none','无'],1:['fire','火'],2:['ice','冰'],3:['earth','树'],4:['thunder','雷'],5:['light','光'],6:['dark','暗']};
const skillKinds = {0:'全部攻击',1:'特技',2:'魔法',5:'超必杀技',9:'普通攻击',10:'物理攻击（普通攻击／特技）'};
const statSpecs = {
  1030000:{key:'attack',label:'攻击力',statType:2,operation:300},
  1030100:{key:'defense',label:'防御力',statType:3,operation:301},
  1030200:{key:'intelligence',label:'法强',statType:4,operation:302},
  1030300:{key:'mind',label:'魔抗',statType:5,operation:303},
  1030500:{key:'hp',label:'HP',statType:0,operation:305},
  1031800:{key:'mp',label:'MP',statType:1,operation:318}
};
const sourceRoot='reverse_damage/scripts_v31/';
const evidence=(file,line,description)=>({file:sourceRoot+file,line,description});
const percentageEvidence=[evidence('luaCommon.lua',24,'万分率换算：raw × 0.0001；展示百分比为raw / 100'),evidence('procCondCommon.lua',2729,'EditDamagePer按当前伤害逐条乘(1 + raw × 0.0001)后round，最低1')];
const equipmentEvidence=evidence('luaCommon.lua',601,'装备类型枚举：10剑/11斧/12枪/13槌/14弓/15机械/16爪/17杖/20铠/21衣/22袍');
const elementEvidence=evidence('luaCommon.lua',535,'元素枚举：0无/1火/2冰/3树/4雷/5光/6暗');
const skillEvidence=[evidence('luaCommon.lua',185,'技能类型：9普攻、1特技、2魔法、5超必、10物理分类'),evidence('luaCommon.lua',212,'物理技能分类仅含普通攻击与特技；不是参照ATK或INT'),evidence('procCondCommon.lua',2632,'技能类型条件0不限制技能类别')];
function attackConditions(id,incoming=false) {
  if(id===0)return [];
  if(incoming) return [EQ('incomingAttackKind',id===10?'physical':id===2?'magic':id===5?'ultimate':id===1?'skill':'normal')];
  return id===10?[IN('attackKind',['normal','skill'])]:[EQ('attackKind',({1:'skill',2:'magic',5:'ultimate',9:'normal'})[id])];
}
function describe(entry) {
  const p=entry.raw.values, pid=entry.processId, conditionId=entry.conditionId;
  const info={localId:entry.raw.localId,processId:pid,conditionId,conditionParams:[...entry.raw.conditionParams],
    value:null,type:null,target:null,unit:'%',conditions:[],equipId:null,equipLabel:null,elementId:null,elementLabel:null,
    attackTypeId:null,attackTypeLabel:null,parameterIndex:null,externalConditionImplementationVerified:false,
    evidence:[],sourceId:`account-blessing-${entry.raw.localId}`};
  const equip=id=>{const [field,label]=equipment[id];info.equipId=id;info.equipLabel=label;info.conditions.push(EQ(field,true));info.evidence.push(equipmentEvidence);};
  const element=(id,incoming=false)=>{const [field,label]=elements[id];info.elementId=id;info.elementLabel=label;info.conditions.push(EQ(incoming?'incomingElement':'element',field));info.evidence.push(elementEvidence);};
  const attack=(id,incoming=false)=>{info.attackTypeId=id;info.attackTypeLabel=skillKinds[id];info.conditions.push(...attackConditions(id,incoming));info.evidence.push(...skillEvidence);};
  if(statSpecs[pid]) {
    const s=statSpecs[pid];info.type='stat';info.target=s.label;info.statKey=s.key;info.value=p[1]/100;info.parameterIndex=1;
    info.name=`加护 · ${s.label}`;info.text=`${s.label}+${info.value}%。`;
    info.evidence=[evidence('procCondCommon.lua',338,'原生六维ControlTypes操作：STR300/DEF301/INT302/MND303/最大HP305/最大MP318'),evidence('luaCommon.lua',24,'万分率转百分比：mul / 100')];
    info.evidence.push({file:ACCOUNT_BLESSING_META.sourceReport,line:1,description:`localId=${info.localId}，原生operation=${s.operation}，condition=1000，conditionParams全0，component=mul，statType=${s.statType}`});
    info.verification='description';return info;
  }
  let line;
  switch(pid) {
    case 1050253:
      info.type='damage';info.target='物理伤害';equip(p[0]);attack(10);info.parameterIndex=1;line=17472;break;
    case 1050463:
      info.type='damage';attack(p[0]);info.target=p[0]===5?'超必杀技伤害':`${skillKinds[p[0]]}伤害`;info.parameterIndex=1;line=19417;break;
    case 1050450:
      info.type='damage';element(p[0]);info.target=`${info.elementLabel}属性伤害`;info.parameterIndex=1;line=19312;break;
    case 1050415:
      info.type='defense';element(p[0],true);info.target=`受到的${info.elementLabel}属性伤害`;info.parameterIndex=1;line=18837;break;
    case 1050200:
      info.type='defense';equip(p[0]);attack(10,true);info.target='受到的物理伤害';info.parameterIndex=1;line=16750;break;
    case 1050513:
      info.type='defense';equip(p[0]);attack(p[1],true);info.target=p[1]===2?'受到的魔法伤害':`受到的${skillKinds[p[1]]}伤害`;info.parameterIndex=2;line=20084;break;
    case 1082601:
      info.type='cap';info.unit='';attack(p[0]);info.target=p[0]===5?'超必杀技伤害上限':`${skillKinds[p[0]]}伤害上限`;info.parameterIndex=1;line=27473;break;
    case 1082604:
      info.type='cap';info.unit='';element(p[0]);attack(p[1]);info.target=`${info.elementLabel}属性伤害上限`;info.parameterIndex=2;line=27502;break;
    case 1082608:
      info.type='cap';info.unit='';equip(p[0]);attack(p[1]);info.target=p[1]===2?'魔法伤害上限':p[1]===10?'物理伤害上限':`${skillKinds[p[1]]}伤害上限`;info.parameterIndex=2;line=27542;break;
    default: return null;
  }
  info.value=p[info.parameterIndex]/(info.unit==='%'?100:1);
  info.name=`加护 · ${info.equipLabel?info.equipLabel+' · ':''}${info.target}`;
  const prefix=[info.equipLabel?`装备${info.equipLabel}时`:null,info.attackTypeId===10?'限普通攻击或特技':null].filter(Boolean).join('；');
  info.text=`${prefix?prefix+'，':''}${info.target}${info.value>=0?'+':''}${info.value}${info.unit}。`;
  info.evidence.unshift(evidence('process.lua',line,`process${pid}参数声明及实际调用；Lua params[${info.parameterIndex+1}]为此数值`));
  if(info.type==='cap')info.evidence.push(evidence('procCondCommon.lua',2773,'EditDamageLimit传固定加值、万分率和后加值；本记录倍率为0'),evidence('procCondCommon.lua',437,'DmgLimitUp参数：增减值、增减倍率、倍率计算后增减值'));
  else info.evidence.push(...percentageEvidence);
  info.evidence.push({file:ACCOUNT_BLESSING_META.sourceReport,line:1,description:`localId=${info.localId}，processId=${pid}，conditionId=${conditionId}，外层conditionParams未逐位解码；配置语义不代表当前命中已生效`});
  info.verification='untested';return info;
}
